SourceCode.Declaration:
abstract class TFMSearchHandler
{

    Set                         idUsed;
    TFMRequestSearchElement     request;
    TFMSearchResponseElement    response;
}

Method.Source:
/// <summary>
/// Constructor For searching items
/// </summary>
public void new()
{    
    idUsed      = new Set(Types::String);
    response    = new TFMSearchResponseElement();

}

public TFMSearchResponseElement getResponse()
{
    response.parmSearchRequest(request);
    return response;
}

public TFMRequestSearchElement parmSearchRequest(TFMRequestSearchElement _searchRequest = request)
{
    request = _searchRequest;
    return request;
}

/// <summary>
/// Method to create the filter/header for the Default search page.
/// </summary>
/// <param name = "_label">The Label for the filter field</param>
/// <param name = "_id">The ID of the field.</param>
/// <param name = "_name">The Name of the field.</param>
protected TFMRegistrationCollectorText addDefaultSearchField(str _label, int _id = 1, str _name = TFMConstants::SearchValue())
{
    return new TFMRegistrationCollectorText(_id,_name,_label,_label,_label);        
}

public static TFMSearchHandler getSearchHandlerFromType(TFMRequestSearchElement _searchRequest)
{
    TFMSearchHandler    result  = null;
    result = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMSearchHandler), new TFMSearchTypeAttribute(_searchRequest.parmType()));

    if (result == null && tableName2Id(strReplace(_searchRequest.parmType(),'_' + TFMConstants::Search(),'' )))
    {
        // Search is generic table search
        result = new TFMSearchGenericTable();
    }
    if (result)
    {
        result.parmSearchRequest(_searchRequest);
    }
    return result;
}

/// <summary>
/// Method to add a result element with the given content.
/// </summary>
/// <param name = "_id">The ID of the element.</param>
/// <param name = "_name">Element name</param>
/// <param name = "_originRecord">The buffer from which the data originated from.</param>
/// <param name = "_displayLine1">Content for display line 1</param>
/// <param name = "_displayLine2">Content for display line 2</param>
/// <param name = "_displayLine3">Content for display line 3</param>
protected void addResult(Str _id, Str _name, Common _originRecord, Str _displayLine1 = '', Str _displayLine2 = '', Str _displayLine3 = '', str _imageId = '')
{
    Str id = strLTrim(_id);
    response.addResponse(_originRecord,id,_displayLine1, _displayLine2 , _displayLine3, _imageId);
}
